//! Integration test against images generated by macOS's own `newfs_msdos`.
//! Skips (with a message) where the tool is unavailable.
use std::process::Command;

#[test]
fn detects_fat32_made_by_newfs_msdos() {
    let dir = std::env::temp_dir().join(format!("voluma-it-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let img = dir.join("fat32.img");
    let f = std::fs::File::create(&img).unwrap();
    f.set_len(64 << 20).unwrap();
    drop(f);
    let ok = Command::new("newfs_msdos").args(["-F", "32", "-v", "VOLTEST"]).arg(&img).output();
    match ok {
        Ok(o) if o.status.success() => {}
        _ => { eprintln!("newfs_msdos unavailable; skipping"); return; }
    }
    let v: serde_json::Value = serde_json::from_str(&voluma_ffi::inspect_image_json(img.to_str().unwrap())).unwrap();
    let fs = &v["ok"]["whole_disk_filesystem"];
    assert_eq!(fs["kind"], "fat32", "{v}");
    assert_eq!(fs["label"], "VOLTEST", "{v}");
    std::fs::remove_dir_all(dir).ok();
}
